/**
 * @param {Function} fn
 * @return {Object}
 */
Array.prototype.groupBy = function(fn) {
    const groups = {}; // key -> array of items, in original order

    for (const item of this) {            // `this` is the array (regular function, not arrow)
        const key = fn(item);
        // own-property check, so keys like "constructor" or "toString" don't hit Object.prototype
        if (!Object.prototype.hasOwnProperty.call(groups, key)) {
            groups[key] = [];
        }
        groups[key].push(item);
    }
    return groups;
};

/**
 * [1,2,3].groupBy(String) // {"1":[1],"2":[2],"3":[3]}
 */
